const wk = new Date(Date.now()-6*864e5).toISOString().slice(0,10);
const agg = {};
items.map(i=>i.json).filter(r=>r.Date>=wk).forEach(r=>{const s=r.Staff||'—';agg[s]=agg[s]||{n:0,amt:0};agg[s].n++;agg[s].amt+=Number(String(r.Amount).replace(/\D/g,''))||0});
const rows = Object.entries(agg).sort((a,b)=>b[1].amt-a[1].amt);
const medals=['🥇','🥈','🥉'];
return [{ json: { text: rows.length ? '🏆 Weekly staff leaderboard:\n'+rows.map(([s,v],i)=>`${medals[i]||'▫️'} ${s} — ₹${v.amt.toLocaleString('en-IN')} (${v.n} sales)`).join('\n')+'\n\nShare it with the team — celebrate the winner! 🎉' : 'No staff sales logged this week — remind the team to log every bill.' } }];

const today = new Date();
const rows = items.map(i=>i.json).map(r=>({ ...r, days: Math.round((new Date(r.DueDate)-today)/864e5) })).filter(r=>r.DueDate && r.days<=7 && r.days>=-2);
if (!rows.length) return [];
return [{ json: { text: '📋 Compliance due soon:\n'+rows.map(r=>`${r.days<0?'🔴 OVERDUE':'⏳ '+r.days+'d'} — ${r.Item}${r.Notes?' ('+r.Notes+')':''} [${r.DueDate}]`).join('\n') } }];
